The complete `solution.py` below extracts text from a ruled grid. `row_edges` and `column_edges` must each be lists of at least two strictly increasing finite numbers. `labels` contains `(x, y, text)` tuples with finite numeric coordinates and string text. Boolean coordinates are invalid. Labels outside the half-open grid bounds are ignored. Every cell is returned, including empty cells, as a rectangular list of rows. Labels in a cell must be joined with one space in reading order: increasing `y`, then increasing `x`; equal coordinates retain input order. Inputs must not be mutated. Repair the single semantic bug and return the corrected complete source file.

```python
import bisect
import math


def read_ruled_grid(row_edges: list, column_edges: list, labels: list) -> list[list[str]]:
    def validate_edges(edges, name):
        if not isinstance(edges, list) or len(edges) < 2:
            raise ValueError(f"{name} must contain at least two edges")
        for value in edges:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError(f"{name} must be numeric")
            if not math.isfinite(value):
                raise ValueError(f"{name} must be finite")
        if any(a >= b for a, b in zip(edges, edges[1:])):
            raise ValueError(f"{name} must be strictly increasing")

    validate_edges(row_edges, "row_edges")
    validate_edges(column_edges, "column_edges")
    cells = [[[] for _ in range(len(column_edges) - 1)] for _ in range(len(row_edges) - 1)]
    for order, label in enumerate(labels):
        if not isinstance(label, tuple) or len(label) != 3:
            raise ValueError("each label must be an (x, y, text) tuple")
        x, y, text = label
        if isinstance(x, bool) or isinstance(y, bool) or not isinstance(x, (int, float)) or not isinstance(y, (int, float)):
            raise TypeError("coordinates must be numeric")
        if not math.isfinite(x) or not math.isfinite(y):
            raise ValueError("coordinates must be finite")
        if not isinstance(text, str):
            raise TypeError("text must be a string")
        row = bisect.bisect_right(row_edges, y) - 1
        column = bisect.bisect_right(column_edges, x) - 1
        if 0 <= row < len(cells) and 0 <= column < len(cells[0]) and y < row_edges[-1] and x < column_edges[-1]:
            cells[row][column].append((x, y, order, text))
    return [[" ".join(item[3] for item in sorted(cell, key=lambda item: (item[0], item[1], item[2]))) for cell in row] for row in cells]
```

